static std::vector<std::byte>
make_bmff_foreign_file_offset_meta_box(uint32_t image_payload_offset,
                                       bool include_iprp         = false,
                                       bool include_existing_icc = false)
{
    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> infe_payload;
    append_bmff_fullbox_header(&infe_payload, 2U);
    append_u16be(&infe_payload, 1U);
    append_u16be(&infe_payload, 0U);
    append_fourcc(&infe_payload, openmeta::fourcc('h', 'v', 'c', '1'));
    append_bytes(&infe_payload, "Primary");
    infe_payload.push_back(std::byte { 0x00 });
    std::vector<std::byte> infe_box;
    append_bmff_box(&infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(infe_payload.data(),
                                               infe_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, 1U);
    iinf_payload.insert(iinf_payload.end(), infe_box.begin(), infe_box.end());
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 1U);
    iloc_payload.push_back(std::byte { 0x44 });
    iloc_payload.push_back(std::byte { 0x00 });
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 0U);
    append_u16be(&iloc_payload, 0U);
    append_u16be(&iloc_payload, 1U);
    append_u32be(&iloc_payload, image_payload_offset);
    append_u32be(&iloc_payload, 4U);
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> iprp_box;
    if (include_iprp) {
        std::vector<std::byte> ispe_payload;
        append_bmff_fullbox_header(&ispe_payload, 0U);
        append_u32be(&ispe_payload, 64U);
        append_u32be(&ispe_payload, 32U);
        std::vector<std::byte> ispe_box;
        append_bmff_box(&ispe_box, openmeta::fourcc('i', 's', 'p', 'e'),
                        std::span<const std::byte>(ispe_payload.data(),
                                                   ispe_payload.size()));

        std::vector<std::byte> ipco_box;
        std::vector<std::byte> ipco_payload;
        ipco_payload.insert(ipco_payload.end(), ispe_box.begin(),
                            ispe_box.end());
        if (include_existing_icc) {
            std::vector<std::byte> old_icc_payload;
            append_fourcc(&old_icc_payload,
                          openmeta::fourcc('p', 'r', 'o', 'f'));
            old_icc_payload.push_back(std::byte { 'O' });
            old_icc_payload.push_back(std::byte { 'L' });
            old_icc_payload.push_back(std::byte { 'D' });
            old_icc_payload.push_back(std::byte { '!' });
            std::vector<std::byte> old_icc_box;
            append_bmff_box(&old_icc_box, openmeta::fourcc('c', 'o', 'l', 'r'),
                            std::span<const std::byte>(old_icc_payload.data(),
                                                       old_icc_payload.size()));
            ipco_payload.insert(ipco_payload.end(), old_icc_box.begin(),
                                old_icc_box.end());
        }
        append_bmff_box(&ipco_box, openmeta::fourcc('i', 'p', 'c', 'o'),
                        std::span<const std::byte>(ipco_payload.data(),
                                                   ipco_payload.size()));

        std::vector<std::byte> ipma_payload;
        append_bmff_fullbox_header(&ipma_payload, 0U);
        append_u32be(&ipma_payload, 1U);
        append_u16be(&ipma_payload, 1U);
        ipma_payload.push_back(include_existing_icc ? std::byte { 0x02 }
                                                    : std::byte { 0x01 });
        ipma_payload.push_back(std::byte { 0x01 });
        if (include_existing_icc) {
            ipma_payload.push_back(std::byte { 0x02 });
        }
        std::vector<std::byte> ipma_box;
        append_bmff_box(&ipma_box, openmeta::fourcc('i', 'p', 'm', 'a'),
                        std::span<const std::byte>(ipma_payload.data(),
                                                   ipma_payload.size()));

        std::vector<std::byte> iprp_payload;
        iprp_payload.insert(iprp_payload.end(), ipco_box.begin(),
                            ipco_box.end());
        iprp_payload.insert(iprp_payload.end(), ipma_box.begin(),
                            ipma_box.end());
        append_bmff_box(&iprp_box, openmeta::fourcc('i', 'p', 'r', 'p'),
                        std::span<const std::byte>(iprp_payload.data(),
                                                   iprp_payload.size()));
    }

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    if (include_iprp) {
        meta_payload.insert(meta_payload.end(), iprp_box.begin(),
                            iprp_box.end());
    }

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    return meta_box;
}

static std::vector<std::byte>
make_bmff_foreign_meta_before_mdat_target()
{
    const std::array<uint32_t, 2> compat = {
        openmeta::fourcc('m', 'i', 'f', '1'),
        openmeta::fourcc('h', 'e', 'i', 'c'),
    };

    std::vector<std::byte> ftyp_payload;
    append_fourcc(&ftyp_payload, openmeta::fourcc('h', 'e', 'i', 'c'));
    append_u32be(&ftyp_payload, 0U);
    for (size_t i = 0; i < compat.size(); ++i) {
        append_fourcc(&ftyp_payload, compat[i]);
    }
    std::vector<std::byte> ftyp_box;
    append_bmff_box(&ftyp_box, openmeta::fourcc('f', 't', 'y', 'p'),
                    std::span<const std::byte>(ftyp_payload.data(),
                                               ftyp_payload.size()));

    std::vector<std::byte> meta_box = make_bmff_foreign_file_offset_meta_box(
        0U);
    const uint32_t mdat_payload_offset = static_cast<uint32_t>(
        ftyp_box.size() + meta_box.size() + 8U);
    meta_box = make_bmff_foreign_file_offset_meta_box(mdat_payload_offset);

    static const std::array<std::byte, 4> kMediaData = {
        std::byte { 0xAA },
        std::byte { 0xBB },
        std::byte { 0xCC },
        std::byte { 0xDD },
    };
    std::vector<std::byte> mdat_box;
    append_bmff_box(&mdat_box, openmeta::fourcc('m', 'd', 'a', 't'),
                    std::span<const std::byte>(kMediaData.data(),
                                               kMediaData.size()));

    std::vector<std::byte> out;
    out.insert(out.end(), ftyp_box.begin(), ftyp_box.end());
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    out.insert(out.end(), mdat_box.begin(), mdat_box.end());
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_existing_ipma_target()
{
    std::vector<std::byte> out = make_minimal_bmff_file();
    std::vector<std::byte> meta_box
        = make_bmff_foreign_file_offset_meta_box(0U, true);
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_existing_icc_property_target()
{
    std::vector<std::byte> out = make_minimal_bmff_file();
    std::vector<std::byte> meta_box
        = make_bmff_foreign_file_offset_meta_box(0U, true, true);
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_multi_item_existing_icc_property_target(
    bool mark_icc_essential)
{
    std::vector<std::byte> out = make_minimal_bmff_file();

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, 2U);
    append_test_bmff_infe_v2(&iinf_payload, 1U,
                             openmeta::fourcc('h', 'v', 'c', '1'), "Primary");
    append_test_bmff_infe_v2(&iinf_payload, 2U,
                             openmeta::fourcc('h', 'v', 'c', '1'), "Aux");
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 1U);
    iloc_payload.push_back(std::byte { 0x44 });
    iloc_payload.push_back(std::byte { 0x40 });
    append_u16be(&iloc_payload, 2U);
    for (uint16_t item_id = 1U; item_id <= 2U; ++item_id) {
        append_u16be(&iloc_payload, item_id);
        append_u16be(&iloc_payload, 0x0001U);
        append_u16be(&iloc_payload, 0U);
        append_u32be(&iloc_payload, 0U);
        append_u16be(&iloc_payload, 1U);
        append_u32be(&iloc_payload, static_cast<uint32_t>(item_id - 1U));
        append_u32be(&iloc_payload, 1U);
    }
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> ispe_payload;
    append_bmff_fullbox_header(&ispe_payload, 0U);
    append_u32be(&ispe_payload, 64U);
    append_u32be(&ispe_payload, 32U);
    std::vector<std::byte> ispe_box;
    append_bmff_box(&ispe_box, openmeta::fourcc('i', 's', 'p', 'e'),
                    std::span<const std::byte>(ispe_payload.data(),
                                               ispe_payload.size()));

    std::vector<std::byte> old_icc_payload;
    append_fourcc(&old_icc_payload, openmeta::fourcc('p', 'r', 'o', 'f'));
    old_icc_payload.push_back(std::byte { 'O' });
    old_icc_payload.push_back(std::byte { 'L' });
    old_icc_payload.push_back(std::byte { 'D' });
    old_icc_payload.push_back(std::byte { '!' });
    std::vector<std::byte> old_icc_box;
    append_bmff_box(&old_icc_box, openmeta::fourcc('c', 'o', 'l', 'r'),
                    std::span<const std::byte>(old_icc_payload.data(),
                                               old_icc_payload.size()));

    std::vector<std::byte> ipco_payload;
    ipco_payload.insert(ipco_payload.end(), ispe_box.begin(), ispe_box.end());
    ipco_payload.insert(ipco_payload.end(), old_icc_box.begin(),
                        old_icc_box.end());
    std::vector<std::byte> ipco_box;
    append_bmff_box(&ipco_box, openmeta::fourcc('i', 'p', 'c', 'o'),
                    std::span<const std::byte>(ipco_payload.data(),
                                               ipco_payload.size()));

    std::vector<std::byte> ipma_payload;
    append_bmff_fullbox_header(&ipma_payload, 0U);
    append_u32be(&ipma_payload, 2U);
    append_u16be(&ipma_payload, 1U);
    ipma_payload.push_back(std::byte { 0x02 });
    ipma_payload.push_back(std::byte { 0x01 });
    ipma_payload.push_back(mark_icc_essential ? std::byte { 0x82 }
                                              : std::byte { 0x02 });
    append_u16be(&ipma_payload, 2U);
    ipma_payload.push_back(std::byte { 0x01 });
    ipma_payload.push_back(mark_icc_essential ? std::byte { 0x82 }
                                              : std::byte { 0x02 });
    std::vector<std::byte> ipma_box;
    append_bmff_box(&ipma_box, openmeta::fourcc('i', 'p', 'm', 'a'),
                    std::span<const std::byte>(ipma_payload.data(),
                                               ipma_payload.size()));

    std::vector<std::byte> iprp_payload;
    iprp_payload.insert(iprp_payload.end(), ipco_box.begin(), ipco_box.end());
    iprp_payload.insert(iprp_payload.end(), ipma_box.begin(), ipma_box.end());
    std::vector<std::byte> iprp_box;
    append_bmff_box(&iprp_box, openmeta::fourcc('i', 'p', 'r', 'p'),
                    std::span<const std::byte>(iprp_payload.data(),
                                               iprp_payload.size()));

    const std::array<std::byte, 2> image_payload = { std::byte { 0xA1 },
                                                     std::byte { 0xA2 } };
    std::vector<std::byte> idat_box;
    append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                    std::span<const std::byte>(image_payload.data(),
                                               image_payload.size()));

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    meta_payload.insert(meta_payload.end(), iprp_box.begin(), iprp_box.end());
    meta_payload.insert(meta_payload.end(), idat_box.begin(), idat_box.end());

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

static bool
find_top_level_bmff_box(std::span<const std::byte> bytes, uint32_t type,
                        size_t* out_offset, size_t* out_size) noexcept
{
    if (!out_offset || !out_size) {
        return false;
    }
    size_t off = 0U;
    while (off + 8U <= bytes.size()) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > bytes.size() - off) {
            return false;
        }
        if (box_type == type) {
            *out_offset = off;
            *out_size   = box_size;
            return true;
        }
        off += box_size;
    }
    return false;
}

static bool
find_top_level_bmff_meta_child_box(std::span<const std::byte> bytes,
                                   uint32_t type, size_t* out_offset,
                                   size_t* out_size) noexcept
{
    if (!out_offset || !out_size) {
        return false;
    }
    size_t meta_off  = 0U;
    size_t meta_size = 0U;
    if (!find_top_level_bmff_box(bytes, openmeta::fourcc('m', 'e', 't', 'a'),
                                 &meta_off, &meta_size)) {
        return false;
    }
    const size_t meta_end = meta_off + meta_size;
    if (meta_off + 12U > meta_end) {
        return false;
    }

    size_t off = meta_off + 12U;
    while (off + 8U <= meta_end) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > meta_end - off) {
            return false;
        }
        if (box_type == type) {
            *out_offset = off;
            *out_size   = box_size;
            return true;
        }
        off += box_size;
    }
    return false;
}

static bool
read_test_bmff_primary_iloc_extent_offset(std::span<const std::byte> bytes,
                                          uint32_t* out_offset) noexcept
{
    if (!out_offset) {
        return false;
    }
    size_t meta_off  = 0U;
    size_t meta_size = 0U;
    if (!find_top_level_bmff_box(bytes, openmeta::fourcc('m', 'e', 't', 'a'),
                                 &meta_off, &meta_size)) {
        return false;
    }

    const size_t meta_end = meta_off + meta_size;
    size_t off            = meta_off + 12U;
    while (off + 8U <= meta_end) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > meta_end - off) {
            return false;
        }
        if (box_type == openmeta::fourcc('i', 'l', 'o', 'c')) {
            const size_t payload = off + 8U;
            const size_t end     = off + box_size;
            if (payload + 8U > end) {
                return false;
            }
            const uint8_t version = std::to_integer<uint8_t>(
                bytes[payload + 0U]);
            const uint8_t sizes0 = std::to_integer<uint8_t>(
                bytes[payload + 4U]);
            const uint8_t sizes1 = std::to_integer<uint8_t>(
                bytes[payload + 5U]);
            const size_t offset_size = static_cast<size_t>((sizes0 >> 4U)
                                                           & 0x0FU);
            const size_t length_size = static_cast<size_t>(sizes0 & 0x0FU);
            const size_t base_size   = static_cast<size_t>((sizes1 >> 4U)
                                                           & 0x0FU);
            const size_t index_size  = static_cast<size_t>(sizes1 & 0x0FU);
            if (version != 1U || offset_size != 4U || length_size != 4U
                || base_size != 0U || index_size != 0U) {
                return false;
            }
            uint16_t item_count = 0U;
            if (!read_test_u16be(bytes, payload + 6U, &item_count)
                || item_count == 0U) {
                return false;
            }
            size_t cursor = payload + 8U;
            if (cursor + 12U > end) {
                return false;
            }
            cursor += 2U;  // item_ID
            cursor += 2U;  // construction_method
            cursor += 2U;  // data_reference_index
            uint16_t extent_count = 0U;
            if (!read_test_u16be(bytes, cursor, &extent_count)
                || extent_count == 0U) {
                return false;
            }
            cursor += 2U;
            return read_test_u32be(bytes, cursor, out_offset);
        }
        off += box_size;
    }
    return false;
}

struct TestBmffIlocRecordInfo final {
    uint32_t item_id              = 0U;
    uint16_t construction_method  = 0U;
    uint16_t data_reference_index = 0U;
    uint64_t base_offset          = 0U;
    uint64_t extent_offset        = 0U;
    uint64_t extent_length        = 0U;
};

static bool
read_test_bmff_iloc_u_nbe(std::span<const std::byte> bytes, size_t* cursor,
                          size_t end, size_t width, uint64_t* out) noexcept
{
    if (!cursor || *cursor > end || width > end - *cursor) {
        return false;
    }
    if (!read_test_u_nbe(bytes, *cursor, width, out)) {
        return false;
    }
    *cursor += width;
    return true;
}

static bool
skip_test_bmff_iloc_u_nbe(size_t* cursor, size_t end, size_t width) noexcept
{
    if (!cursor || *cursor > end || width > end - *cursor) {
        return false;
    }
    *cursor += width;
    return true;
}

static bool
read_test_bmff_iloc_record(std::span<const std::byte> bytes,
                           uint32_t wanted_item_id,
                           TestBmffIlocRecordInfo* out) noexcept
{
    if (!out) {
        return false;
    }
    size_t meta_off  = 0U;
    size_t meta_size = 0U;
    if (!find_top_level_bmff_box(bytes, openmeta::fourcc('m', 'e', 't', 'a'),
                                 &meta_off, &meta_size)) {
        return false;
    }

    const size_t meta_end = meta_off + meta_size;
    if (meta_off + 12U > meta_end) {
        return false;
    }
    size_t off = meta_off + 12U;
    while (off + 8U <= meta_end) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > meta_end - off) {
            return false;
        }
        if (box_type != openmeta::fourcc('i', 'l', 'o', 'c')) {
            off += box_size;
            continue;
        }

        const size_t payload = off + 8U;
        const size_t end     = off + box_size;
        if (payload + 8U > end) {
            return false;
        }
        const uint8_t version = std::to_integer<uint8_t>(bytes[payload + 0U]);
        const uint8_t sizes0  = std::to_integer<uint8_t>(bytes[payload + 4U]);
        const uint8_t sizes1  = std::to_integer<uint8_t>(bytes[payload + 5U]);
        const size_t offset_size = static_cast<size_t>((sizes0 >> 4U) & 0x0FU);
        const size_t length_size = static_cast<size_t>(sizes0 & 0x0FU);
        const size_t base_size   = static_cast<size_t>((sizes1 >> 4U) & 0x0FU);
        const size_t index_size  = static_cast<size_t>(sizes1 & 0x0FU);
        if (version > 2U || offset_size > 8U || length_size > 8U
            || base_size > 8U || index_size > 8U
            || (version == 0U && index_size != 0U)) {
            return false;
        }

        size_t cursor       = payload + 6U;
        uint64_t item_count = 0U;
        if (!read_test_bmff_iloc_u_nbe(bytes, &cursor, end,
                                       version == 2U ? 4U : 2U, &item_count)) {
            return false;
        }
        if (item_count > static_cast<uint64_t>(end - cursor)) {
            return false;
        }

        const size_t item_id_width = version == 2U ? 4U : 2U;
        for (uint64_t i = 0U; i < item_count; ++i) {
            uint64_t raw_item_id = 0U;
            if (!read_test_bmff_iloc_u_nbe(bytes, &cursor, end, item_id_width,
                                           &raw_item_id)
                || raw_item_id > std::numeric_limits<uint32_t>::max()) {
                return false;
            }

            uint64_t raw_construction_method = 0U;
            if (version != 0U
                && !read_test_bmff_iloc_u_nbe(bytes, &cursor, end, 2U,
                                              &raw_construction_method)) {
                return false;
            }

            uint64_t raw_data_reference_index = 0U;
            uint64_t base_offset              = 0U;
            uint64_t extent_count             = 0U;
            if (!read_test_bmff_iloc_u_nbe(bytes, &cursor, end, 2U,
                                           &raw_data_reference_index)
                || !read_test_bmff_iloc_u_nbe(bytes, &cursor, end, base_size,
                                              &base_offset)
                || !read_test_bmff_iloc_u_nbe(bytes, &cursor, end, 2U,
                                              &extent_count)
                || extent_count > static_cast<uint64_t>(end - cursor)) {
                return false;
            }

            uint64_t first_extent_offset = 0U;
            uint64_t first_extent_length = 0U;
            bool has_first_extent        = false;
            for (uint64_t j = 0U; j < extent_count; ++j) {
                uint64_t extent_offset = 0U;
                uint64_t extent_length = 0U;
                if ((version == 0U
                     || skip_test_bmff_iloc_u_nbe(&cursor, end, index_size))
                    && read_test_bmff_iloc_u_nbe(bytes, &cursor, end,
                                                 offset_size, &extent_offset)
                    && read_test_bmff_iloc_u_nbe(bytes, &cursor, end,
                                                 length_size, &extent_length)) {
                    if (j == 0U) {
                        first_extent_offset = extent_offset;
                        first_extent_length = extent_length;
                        has_first_extent    = true;
                    }
                } else {
                    return false;
                }
            }

            if (raw_item_id == wanted_item_id) {
                if (!has_first_extent) {
                    return false;
                }
                out->item_id             = static_cast<uint32_t>(raw_item_id);
                out->construction_method = static_cast<uint16_t>(
                    raw_construction_method & 0x000FULL);
                out->data_reference_index = static_cast<uint16_t>(
                    raw_data_reference_index);
                out->base_offset   = base_offset;
                out->extent_offset = first_extent_offset;
                out->extent_length = first_extent_length;
                return true;
            }
        }
        return false;
    }
    return false;
}

static bool
read_test_bmff_iloc_version(std::span<const std::byte> bytes,
                            uint8_t* out_version) noexcept
{
    if (!out_version) {
        return false;
    }
    size_t iloc_off  = 0U;
    size_t iloc_size = 0U;
    if (!find_top_level_bmff_meta_child_box(
            bytes, openmeta::fourcc('i', 'l', 'o', 'c'), &iloc_off, &iloc_size)
        || iloc_size < 12U || iloc_off + 8U >= bytes.size()) {
        return false;
    }
    *out_version = std::to_integer<uint8_t>(bytes[iloc_off + 8U]);
    return true;
}

static bool
find_test_bmff_child_box(std::span<const std::byte> bytes, size_t begin,
                         size_t end, uint32_t type, size_t* out_offset,
                         size_t* out_size) noexcept
{
    if (!out_offset || !out_size || begin > end || end > bytes.size()) {
        return false;
    }

    size_t off = begin;
    while (off + 8U <= end) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > end - off) {
            return false;
        }
        if (box_type == type) {
            *out_offset = off;
            *out_size   = box_size;
            return true;
        }
        off += box_size;
    }
    return false;
}

static bool
find_top_level_bmff_meta_iprp_child_box(std::span<const std::byte> bytes,
                                        uint32_t type, size_t* out_offset,
                                        size_t* out_size) noexcept
{
    size_t iprp_off  = 0U;
    size_t iprp_size = 0U;
    if (!find_top_level_bmff_meta_child_box(
            bytes, openmeta::fourcc('i', 'p', 'r', 'p'), &iprp_off, &iprp_size)
        || iprp_size < 8U || iprp_off > bytes.size()
        || iprp_size > bytes.size() - iprp_off) {
        return false;
    }
    return find_test_bmff_child_box(bytes, iprp_off + 8U, iprp_off + iprp_size,
                                    type, out_offset, out_size);
}

static bool
append_top_level_bmff_meta_child_box(std::vector<std::byte>* bytes,
                                     std::span<const std::byte> child)
{
    if (!bytes || child.empty()) {
        return false;
    }
    size_t meta_off  = 0U;
    size_t meta_size = 0U;
    if (!find_top_level_bmff_box(std::span<const std::byte>(bytes->data(),
                                                            bytes->size()),
                                 openmeta::fourcc('m', 'e', 't', 'a'),
                                 &meta_off, &meta_size)
        || child.size() > std::numeric_limits<uint32_t>::max() - meta_size) {
        return false;
    }

    bytes->insert(bytes->begin()
                      + static_cast<std::ptrdiff_t>(meta_off + meta_size),
                  child.begin(), child.end());
    return write_test_u32be(bytes, meta_off,
                            static_cast<uint32_t>(meta_size + child.size()));
}

static std::vector<std::byte>
make_test_bmff_iref_v0_single_ref_box(uint32_t ref_type, uint16_t from_item_id,
                                      uint16_t to_item_id)
{
    std::vector<std::byte> ref_payload;
    append_u16be(&ref_payload, from_item_id);
    append_u16be(&ref_payload, 1U);
    append_u16be(&ref_payload, to_item_id);

    std::vector<std::byte> ref_box;
    append_bmff_box(&ref_box, ref_type,
                    std::span<const std::byte>(ref_payload.data(),
                                               ref_payload.size()));

    std::vector<std::byte> iref_payload;
    append_bmff_fullbox_header(&iref_payload, 0U);
    iref_payload.insert(iref_payload.end(), ref_box.begin(), ref_box.end());

    std::vector<std::byte> iref_box;
    append_bmff_box(&iref_box, openmeta::fourcc('i', 'r', 'e', 'f'),
                    std::span<const std::byte>(iref_payload.data(),
                                               iref_payload.size()));
    return iref_box;
}

static bool
duplicate_top_level_bmff_meta_iprp_child_box(std::vector<std::byte>* bytes,
                                             uint32_t type)
{
    if (!bytes) {
        return false;
    }
    size_t meta_off  = 0U;
    size_t meta_size = 0U;
    if (!find_top_level_bmff_box(std::span<const std::byte>(bytes->data(),
                                                            bytes->size()),
                                 openmeta::fourcc('m', 'e', 't', 'a'),
                                 &meta_off, &meta_size)) {
        return false;
    }
    size_t iprp_off  = 0U;
    size_t iprp_size = 0U;
    if (!find_top_level_bmff_meta_child_box(
            std::span<const std::byte>(bytes->data(), bytes->size()),
            openmeta::fourcc('i', 'p', 'r', 'p'), &iprp_off, &iprp_size)) {
        return false;
    }
    size_t child_off  = 0U;
    size_t child_size = 0U;
    if (!find_test_bmff_child_box(std::span<const std::byte>(bytes->data(),
                                                             bytes->size()),
                                  iprp_off + 8U, iprp_off + iprp_size, type,
                                  &child_off, &child_size)) {
        return false;
    }
    if (child_size > std::numeric_limits<uint32_t>::max() - iprp_size
        || child_size > std::numeric_limits<uint32_t>::max() - meta_size) {
        return false;
    }

    const std::vector<std::byte> duplicate(
        bytes->begin() + static_cast<std::ptrdiff_t>(child_off),
        bytes->begin() + static_cast<std::ptrdiff_t>(child_off + child_size));
    bytes->insert(bytes->begin()
                      + static_cast<std::ptrdiff_t>(iprp_off + iprp_size),
                  duplicate.begin(), duplicate.end());
    return write_test_u32be(bytes, iprp_off,
                            static_cast<uint32_t>(iprp_size + duplicate.size()))
           && write_test_u32be(bytes, meta_off,
                               static_cast<uint32_t>(meta_size
                                                     + duplicate.size()));
}

static bool
patch_top_level_bmff_meta_ipma_first_association(std::vector<std::byte>* bytes,
                                                 uint8_t value)
{
    if (!bytes) {
        return false;
    }
    size_t ipma_off  = 0U;
    size_t ipma_size = 0U;
    if (!find_top_level_bmff_meta_iprp_child_box(
            std::span<const std::byte>(bytes->data(), bytes->size()),
            openmeta::fourcc('i', 'p', 'm', 'a'), &ipma_off, &ipma_size)
        || ipma_size < 19U) {
        return false;
    }

    const size_t payload  = ipma_off + 8U;
    const uint8_t version = std::to_integer<uint8_t>((*bytes)[payload]);
    const uint8_t flags2  = std::to_integer<uint8_t>((*bytes)[payload + 3U]);
    if (version != 0U || (flags2 & 1U) != 0U) {
        return false;
    }

    uint32_t entry_count = 0U;
    uint16_t item_id     = 0U;
    if (!read_test_u32be(std::span<const std::byte>(bytes->data(),
                                                    bytes->size()),
                         payload + 4U, &entry_count)
        || !read_test_u16be(std::span<const std::byte>(bytes->data(),
                                                       bytes->size()),
                            payload + 8U, &item_id)
        || entry_count == 0U || item_id == 0U) {
        return false;
    }

    const size_t association_count_off = payload + 10U;
    const size_t first_association_off = payload + 11U;
    if (first_association_off >= ipma_off + ipma_size
        || (*bytes)[association_count_off] == std::byte { 0U }) {
        return false;
    }
    (*bytes)[first_association_off] = static_cast<std::byte>(value);
    return true;
}

static bool
read_test_bmff_iref_version(std::span<const std::byte> bytes,
                            uint8_t* out_version) noexcept
{
    if (!out_version) {
        return false;
    }
    size_t iref_off  = 0U;
    size_t iref_size = 0U;
    if (!find_top_level_bmff_meta_child_box(
            bytes, openmeta::fourcc('i', 'r', 'e', 'f'), &iref_off, &iref_size)
        || iref_size < 12U || iref_off + 8U >= bytes.size()) {
        return false;
    }
    *out_version = std::to_integer<uint8_t>(bytes[iref_off + 8U]);
    return true;
}

static bool
count_test_bmff_iref_relations(std::span<const std::byte> bytes,
                               uint32_t ref_type, bool require_from_id,
                               uint32_t from_item_id, uint32_t to_item_id,
                               uint32_t* out_count) noexcept
{
    if (!out_count) {
        return false;
    }
    *out_count = 0U;

    size_t iref_off  = 0U;
    size_t iref_size = 0U;
    if (!find_top_level_bmff_meta_child_box(
            bytes, openmeta::fourcc('i', 'r', 'e', 'f'), &iref_off, &iref_size)
        || iref_size < 12U || iref_off > bytes.size()
        || iref_size > bytes.size() - iref_off) {
        return false;
    }

    const size_t payload  = iref_off + 8U;
    const size_t end      = iref_off + iref_size;
    const uint8_t version = std::to_integer<uint8_t>(bytes[payload]);
    if (version > 1U) {
        return false;
    }

    const size_t id_width = version == 0U ? 2U : 4U;
    size_t off            = payload + 4U;
    while (off + 8U <= end) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > end - off) {
            return false;
        }

        const size_t child_end = off + box_size;
        size_t cursor          = off + 8U;
        while (cursor < child_end) {
            uint64_t raw_from  = 0U;
            uint16_t ref_count = 0U;
            if (!read_test_u_nbe(bytes, cursor, id_width, &raw_from)
                || raw_from > std::numeric_limits<uint32_t>::max()
                || cursor + id_width > child_end) {
                return false;
            }
            cursor += id_width;
            if (cursor + 2U > child_end
                || !read_test_u16be(bytes, cursor, &ref_count)) {
                return false;
            }
            cursor += 2U;
            for (uint16_t i = 0U; i < ref_count; ++i) {
                uint64_t raw_to = 0U;
                if (!read_test_u_nbe(bytes, cursor, id_width, &raw_to)
                    || raw_to > std::numeric_limits<uint32_t>::max()
                    || cursor + id_width > child_end) {
                    return false;
                }
                cursor += id_width;
                const bool from_matches = !require_from_id
                                          || static_cast<uint32_t>(raw_from)
                                                 == from_item_id;
                if (box_type == ref_type && from_matches
                    && static_cast<uint32_t>(raw_to) == to_item_id) {
                    *out_count += 1U;
                }
            }
        }
        off += box_size;
    }
    return off == end;
}

static bool
count_test_bmff_grpl_entities(std::span<const std::byte> bytes,
                              uint32_t group_type, uint32_t entity_id,
                              uint32_t* out_count) noexcept
{
    if (!out_count) {
        return false;
    }
    *out_count = 0U;

    size_t grpl_off  = 0U;
    size_t grpl_size = 0U;
    if (!find_top_level_bmff_meta_child_box(
            bytes, openmeta::fourcc('g', 'r', 'p', 'l'), &grpl_off, &grpl_size)
        || grpl_size < 8U || grpl_off > bytes.size()
        || grpl_size > bytes.size() - grpl_off) {
        return false;
    }

    const size_t end = grpl_off + grpl_size;
    size_t off       = grpl_off + 8U;
    while (off + 8U <= end) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 20U
            || box_size > end - off) {
            return false;
        }
        const size_t payload = off + 8U;
        if (bytes[payload] != std::byte { 0U }) {
            return false;
        }
        uint32_t entity_count = 0U;
        if (!read_test_u32be(bytes, payload + 8U, &entity_count)
            || entity_count > (box_size - 20U) / 4U) {
            return false;
        }
        size_t cursor = payload + 12U;
        for (uint32_t i = 0U; i < entity_count; ++i) {
            uint32_t value = 0U;
            if (!read_test_u32be(bytes, cursor, &value)) {
                return false;
            }
            if (box_type == group_type && value == entity_id) {
                *out_count += 1U;
            }
            cursor += 4U;
        }
        off += box_size;
    }
    return off == end;
}

static bool
read_test_bmff_ipma_item_property_stats(std::span<const std::byte> bytes,
                                        uint32_t item_id,
                                        uint32_t property_index,
                                        uint32_t* out_association_count,
                                        uint32_t* out_property_count,
                                        uint32_t* out_essential_count) noexcept
{
    if (!out_association_count || !out_property_count || !out_essential_count
        || property_index == 0U || property_index > 0x7FFFU) {
        return false;
    }
    *out_association_count = 0U;
    *out_property_count    = 0U;
    *out_essential_count   = 0U;

    size_t ipma_off  = 0U;
    size_t ipma_size = 0U;
    if (!find_top_level_bmff_meta_iprp_child_box(
            bytes, openmeta::fourcc('i', 'p', 'm', 'a'), &ipma_off, &ipma_size)
        || ipma_size < 16U || ipma_off > bytes.size()
        || ipma_size > bytes.size() - ipma_off) {
        return false;
    }

    const size_t payload  = ipma_off + 8U;
    const size_t end      = ipma_off + ipma_size;
    const uint8_t version = std::to_integer<uint8_t>(bytes[payload]);
    if (version > 1U) {
        return false;
    }
    uint32_t flags = 0U;
    flags |= static_cast<uint32_t>(std::to_integer<uint8_t>(bytes[payload + 1U]))
             << 16U;
    flags |= static_cast<uint32_t>(std::to_integer<uint8_t>(bytes[payload + 2U]))
             << 8U;
    flags |= static_cast<uint32_t>(
        std::to_integer<uint8_t>(bytes[payload + 3U]));

    uint32_t entry_count = 0U;
    if (!read_test_u32be(bytes, payload + 4U, &entry_count)) {
        return false;
    }

    const size_t item_id_width = version == 0U ? 2U : 4U;
    const size_t assoc_width   = (flags & 1U) != 0U ? 2U : 1U;
    size_t cursor              = payload + 8U;
    bool found                 = false;
    for (uint32_t i = 0U; i < entry_count; ++i) {
        uint64_t raw_item_id = 0U;
        if (!read_test_u_nbe(bytes, cursor, item_id_width, &raw_item_id)
            || raw_item_id > std::numeric_limits<uint32_t>::max()
            || cursor + item_id_width > end) {
            return false;
        }
        cursor += item_id_width;
        if (cursor + 1U > end) {
            return false;
        }
        const uint8_t association_count = std::to_integer<uint8_t>(
            bytes[cursor]);
        cursor += 1U;
        if (cursor + static_cast<size_t>(association_count) * assoc_width
            > end) {
            return false;
        }

        const bool item_matches = static_cast<uint32_t>(raw_item_id) == item_id;
        if (item_matches) {
            found = true;
            *out_association_count += association_count;
        }
        for (uint8_t j = 0U; j < association_count; ++j) {
            uint64_t raw_property = 0U;
            if (!read_test_u_nbe(bytes, cursor, assoc_width, &raw_property)) {
                return false;
            }
            cursor += assoc_width;
            const uint32_t normalized
                = assoc_width == 2U
                      ? static_cast<uint32_t>(raw_property & 0x7FFFU)
                      : static_cast<uint32_t>(raw_property & 0x7FU);
            const bool essential = assoc_width == 2U
                                       ? (raw_property & 0x8000U) != 0U
                                       : (raw_property & 0x80U) != 0U;
            if (item_matches && normalized == property_index) {
                *out_property_count += 1U;
                if (essential) {
                    *out_essential_count += 1U;
                }
            }
        }
    }
    return found && cursor == end;
}

static bool
read_test_bmff_ipma_item_property_count(std::span<const std::byte> bytes,
                                        uint32_t item_id,
                                        uint32_t property_index,
                                        uint32_t* out_association_count,
                                        uint32_t* out_property_count) noexcept
{
    uint32_t essential_count = 0U;
    return read_test_bmff_ipma_item_property_stats(bytes, item_id,
                                                   property_index,
                                                   out_association_count,
                                                   out_property_count,
                                                   &essential_count);
}

static std::vector<std::byte>
make_minimal_avif_file()
{
    const std::array<uint32_t, 2> compat = {
        openmeta::fourcc('m', 'i', 'f', '1'),
        openmeta::fourcc('a', 'v', 'i', 'f'),
    };
    return make_minimal_bmff_file(openmeta::fourcc('a', 'v', 'i', 'f'),
                                  std::span<const uint32_t>(compat.data(),
                                                            compat.size()));
}

static std::vector<std::byte>
make_minimal_cr3_file()
{
    const std::array<uint32_t, 2> compat = {
        openmeta::fourcc('c', 'r', 'x', ' '),
        openmeta::fourcc('C', 'R', '3', ' '),
    };
    return make_minimal_bmff_file(openmeta::fourcc('c', 'r', 'x', ' '),
                                  std::span<const uint32_t>(compat.data(),
                                                            compat.size()));
}

static std::vector<std::byte>
make_minimal_jxl_file()
{
    static const std::array<std::byte, 4> kCodestream = {
        std::byte { 0x11 },
        std::byte { 0x22 },
        std::byte { 0x33 },
        std::byte { 0x44 },
    };

    std::vector<std::byte> out;
    append_u32be(&out, 12U);
    append_fourcc(&out, openmeta::fourcc('J', 'X', 'L', ' '));
    append_u32be(&out, 0x0D0A870AU);
    append_bmff_box(&out, openmeta::fourcc('j', 'x', 'l', 'c'),
                    std::span<const std::byte>(kCodestream.data(),
                                               kCodestream.size()));
    return out;
}

#if defined(OPENMETA_HAS_BROTLI) && OPENMETA_HAS_BROTLI \
    && defined(OPENMETA_HAS_BROTLI_ENCODER) && OPENMETA_HAS_BROTLI_ENCODER
static std::vector<std::byte>
brotli_compress(std::span<const std::byte> input)
{
    const size_t max_out = BrotliEncoderMaxCompressedSize(input.size());
    std::vector<uint8_t> out(max_out);
    size_t out_size = out.size();

    const int quality            = 4;
    const int lgwin              = 22;
    const BrotliEncoderMode mode = BROTLI_MODE_GENERIC;

    const uint8_t* in_u8 = reinterpret_cast<const uint8_t*>(input.data());
    const bool ok = BrotliEncoderCompress(quality, lgwin, mode, input.size(),
                                          in_u8, &out_size, out.data());
    if (!ok) {
        return {};
    }

    std::vector<std::byte> bytes(out_size);
    for (size_t i = 0; i < out_size; ++i) {
        bytes[i] = std::byte { out[i] };
    }
    return bytes;
}

static void
append_jxl_brob_box(std::vector<std::byte>* out, uint32_t real_type,
                    std::span<const std::byte> logical_payload)
{
    ASSERT_TRUE(out != nullptr);
    ASSERT_GE(logical_payload.size(), 8U);
    const std::span<const std::byte> payload(logical_payload.data() + 8U,
                                             logical_payload.size() - 8U);
    const std::vector<std::byte> compressed = brotli_compress(payload);
    ASSERT_FALSE(compressed.empty());

    std::vector<std::byte> brob_payload;
    append_fourcc(&brob_payload, real_type);
    brob_payload.insert(brob_payload.end(), compressed.begin(),
                        compressed.end());
    append_bmff_box(out, openmeta::fourcc('b', 'r', 'o', 'b'),
                    std::span<const std::byte>(brob_payload.data(),
                                               brob_payload.size()));
}
#endif

