    const openmeta::TransferSafetyAudit compatible_audit
        = openmeta::transfer_safety_audit_from_store(
            store, openmeta::TransferSafetyMode::CompatibleFile);
    EXPECT_EQ(compatible_audit.safety,
              openmeta::TransferSafetyMode::CompatibleFile);
    EXPECT_EQ(compatible_audit.source_image_properties, 1U);
    EXPECT_EQ(compatible_audit.source_raw_color_calibration,
              expected_rendered_raw_drops);
    EXPECT_EQ(compatible_audit.source_camera_raw_settings, 1U);
    EXPECT_EQ(compatible_audit.source_icc_profiles, 1U);
    EXPECT_EQ(compatible_audit.source_makernotes, 1U);
    EXPECT_EQ(compatible_audit.source_non_c2pa_jumbf, 1U);
    EXPECT_EQ(compatible_audit.source_c2pa, 0U);
    EXPECT_EQ(compatible_audit.filtered_image_properties, 1U);
    EXPECT_EQ(compatible_audit.filtered_raw_color_calibration, 0U);
    EXPECT_EQ(compatible_audit.filtered_camera_raw_settings, 0U);
    EXPECT_EQ(compatible_audit.filtered_icc_profiles, 0U);
    EXPECT_EQ(compatible_audit.filtered_makernotes, 0U);
    EXPECT_EQ(compatible_audit.filtered_non_c2pa_jumbf, 0U);
    EXPECT_EQ(compatible_audit.invalidated_c2pa, 0U);

